                        + (1.0 - w) * rr2 * (1.0 - rr2 ** z) / denom2
                    )
                    used = expected_after - expected_before
                    if used < 0.0:
                        used = 0.0
                    if used > x:
                        used = x
                    stock[idx] = x - used
                    cumulative = cumulative_new
                    expected_before = expected_after

        for i in range(m - 1):
            stock[i] = stock[i + 1]
        stock[m - 1] = 0.0
        if t < len(pipeline):
            stock[m - 1] = pipeline[t]

    projected_total = 0.0
    projected_old = 0.0
    projected_short = 0.0
    for i in range(m):
        x = stock[i]
        projected_total = projected_total + x
        if m > 1:
            oldness = (m - 1.0 - i) / (m - 1.0)
        else:
            oldness = 0.0
        projected_old = projected_old + oldness * x
        if i < L:
            projected_short = projected_short + x

    no_demand_total = 0.0
    no_demand_old = 0.0
    no_demand_short = 0.0

    for i in range(L, m):
        destination = i - L
        x = age[i]
        no_demand_total = no_demand_total + x
        if m > 1:
            oldness = (m - 1.0 - destination) / (m - 1.0)
        else:
            oldness = 0.0
        no_demand_old = no_demand_old + oldness * x
        if destination < L:
            no_demand_short = no_demand_short + x

    for j in range(len(pipeline)):
        destination = m - L + j
        if destination >= 0 and destination < m:
            x = pipeline[j]
            no_demand_total = no_demand_total + x
            if m > 1:
                oldness = (m - 1.0 - destination) / (m - 1.0)
            else:
                oldness = 0.0
            no_demand_old = no_demand_old + oldness * x
            if destination < L:
                no_demand_short = no_demand_short + x

    gap_total = no_demand_total - projected_total
    gap_old = no_demand_old - projected_old
    gap_short = no_demand_short - projected_short

    order = (
        S
        - B0 * projected_total
        - B1 * projected_old
        - B2 * projected_short
        - H0 * gap_total
        - H1 * gap_old
        - H2 * gap_short
    )
    if order < 0.0:
        order = 0.0
    if order > C:
        order = C
    return order
